function largestGroupCount(n: number): number {
  const size = new Map<number, number>();
  for (let i = 1; i <= n; i++) {
    let s = 0;
    for (let x = i; x > 0; x = Math.floor(x / 10)) s += x % 10;
    size.set(s, (size.get(s) ?? 0) + 1);
  }
  const best = Math.max(...size.values());
  let groups = 0;
  for (const c of size.values()) if (c === best) groups++;
  return groups;
}

