function largestGroupCount(n: number): number {
  const ds = new Uint8Array(n + 1);
  const size = new Array(64).fill(0);
  for (let i = 1; i <= n; i++) {
    ds[i] = ds[Math.floor(i / 10)] + (i % 10);
    size[ds[i]]++;
  }
  const best = Math.max(...size);
  return size.filter(c => c === best).length;
}

